(7437771, 1176059, 105457, '<td valign="top">My only 10 in the show. Great mood, beautiful composition. Nothing that I would change, the option for B&amp;W was the right one.</td>', 'My only 10 in the show. Great mood, beautiful composition. Nothing that I would change, the option for B&W was the right one.', '2016-02-17 10:08:26.000000', NULL, 1),
(7437772, 1176109, 105457, '<td valign="top">Superb location, and very uncommon photo. I would increase the clarity or contrast in the stones and sea, but image works well and your colours are gorgeous.</td>', 'Superb location, and very uncommon photo. I would increase the clarity or contrast in the stones and sea, but image works well and your colours are gorgeous.', '2016-02-17 10:09:24.000000', NULL, 1),
(7437773, 1176068, 105457, '<td valign="top">Awesome colors, good choice on the panoramic crop, really adds a lot to the image. My only nitpick would be to straighten the horizon, otherwise it''s a good photo!</td>', 'Awesome colors, good choice on the panoramic crop, really adds a lot to the image. My only nitpick would be to straighten the horizon, otherwise it''s a good photo!', '2016-02-17 10:10:16.000000', NULL, 1),
(7437774, 1176035, 105457, '<td valign="top">If I were to imagine a enchanted story, this would suit the mood perfectly. I love the colors, light and softness of the clouds. I gave it a 9 since it doesn''t remind me of wide open spaces, but a great photo nonetheless.</td>', 'If I were to imagine a enchanted story, this would suit the mood perfectly. I love the colors, light and softness of the clouds. I gave it a 9 since it doesn''t remind me of wide open spaces, but a great photo nonetheless.', '2016-02-17 10:11:46.000000', NULL, 1),
(7437775, 1176006, 105457, '<td valign="top">It''s really amazing would you could get such a bird''s eye view of this. Fits the challenge topic to the T. I would probably sharpen it a bit more, but otherwise it''s a good photo.</td>', 'It''s really amazing would you could get such a bird''s eye view of this. Fits the challenge topic to the T. I would probably sharpen it a bit more, but otherwise it''s a good photo.', '2016-02-17 10:12:56.000000', NULL, 1),
